/* Illustrated inventory tiles and warm paper-and-jade shop/dialog panels. */
MW.itemIconIndex=item=>{if(item.id==='ore')return 14;if(item.id==='herb')return 15;if(item.type==='use')return{potion:0,ether:1,meal:2,ward:3}[item.id];if(item.type==='weapon')return item.kind==='bow'?5:item.kind==='staff'?6:4;if(item.type==='armor')return item.job==='warrior'?8:item.job==='archer'?9:item.job==='mage'?10:7;return item.tier===1?11:item.tier===2?12:13;};
MW.itemReady=typeof Image==='undefined'?Promise.resolve():new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{MW.characterAssets.items=image;resolve();};image.onerror=()=>reject(new Error('items'));image.src='assets/items-2d.webp?v=13';});
MW.characterReady=Promise.all([MW.characterReady,MW.itemReady]);
MW.installBoutique=function(Game){const P=Game.prototype,show=P.show,button=P.button,forge=P.forge;
P.itemIllustration=function(item,size=52){const wrap=document.createElement('div');wrap.className='item-illustration';wrap.dataset.tier=String(item.tier||1);const canvas=document.createElement('canvas');canvas.width=canvas.height=96;canvas.setAttribute?.('aria-label',item.name);canvas.getContext('2d').drawImage(this.renderer.paintedCell('items',MW.itemIconIndex(item),4,4,48,48),0,0,96,96);wrap.style.width=wrap.style.height=size+'px';wrap.append(canvas);if(item.tier){const badge=document.createElement('span');badge.className='item-tier';badge.textContent='T'+item.tier;wrap.append(badge);}return wrap;};
P.button=function(card,label,fn){button.call(this,card,label,fn);const title=card.children[0]?.textContent,item=MW.items.find(i=>title===i.name||title?.startsWith(i.name+' ·'));if(item&&!card.dataset.illustrated){card.dataset.illustrated='true';card.className+=' item-card';card.append(this.itemIllustration(item));}};
P.show=function(speaker,title,text,choices=[]){show.call(this,speaker,title,text,choices);$('#dialogtitle').textContent=title.replace(/ · \d+냥$/,'');const npc=this.world.npcs.find(n=>n.name===speaker),theme=title==='별철 공방'?'forge':title.includes('상점')?'shop':typeof text==='string'?'story':'ledger';dialog.dataset.theme=theme;$('#dialog-wallet').textContent=this.p.gold+'냥';const portrait=$('#dialog-portrait'),c=portrait.getContext('2d');c.clearRect(0,0,portrait.width,portrait.height);c.imageSmoothingEnabled=true;c.drawImage(npc?this.renderer.hero(npc.color):this.renderer.player(this.p,0,0),0,0,portrait.width,portrait.height);$('#dialog-caption').textContent=theme==='shop'?'마음에 드는 물건을 골라 보세요':theme==='forge'?'별철과 정성을 더하는 작은 공방':theme==='story'?'달빛 아래, 당신에게 전하는 이야기':'여행의 준비와 기록';};
P.forge=function(n){forge.call(this,n);const board=document.createElement('section');board.className='forge-board';const item=MW.items.find(i=>i.id===this.p.equip.weapon);if(item)board.append(this.itemIllustration(item,80));const heading=document.createElement('strong');heading.textContent=item?item.name+' +'+this.p.upgrade:'장착한 무기가 없습니다';board.append(heading);const meter=document.createElement('div');meter.className='forge-progress';for(let i=1;i<=10;i++){const dot=document.createElement('span');dot.className=i<=this.p.upgrade?'lit':'';dot.textContent=i===5||i===10?'✦':'•';meter.append(dot);}board.append(meter);const materials=document.createElement('div');materials.className='forge-materials';for(const [id,name]of [['ore','강화석'],['herb','약초']]){const row=document.createElement('div');row.append(this.itemIllustration({id,name},38));const label=document.createElement('span');label.textContent=name+' '+this.p.bag[id];row.append(label);materials.append(row);}board.append(materials);$('#dialogtext').append(board);};
};
